WITH with_windows AS (SELECT id, category, tags, supplier_id, AVG(stock_qty) OVER w_ordered AS stock_qty_avg_2_prior, NTILE(10) OVER (ORDER BY price DESC, id) AS price_bucket, ROUND(cost / SUM(cost) OVER (PARTITION BY supplier_id, brand), 4) AS cost_share FROM products WHERE ARRAY_CONTAINS(tags, 'clearance') WINDOW w_ordered AS (PARTITION BY category ORDER BY launch_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING)) SELECT id, supplier_id, stock_qty_avg_2_prior, price_bucket, cost_share FROM with_windows;
